%% =========================================================================
%% TRANSFORMER PROTECTION DATASET - FEATURE EXTRACTION FOR LSTM
%% =========================================================================
% Converts raw current waveforms into wavelet energy features for AI training
%
% Input:  Raw dataset with 1601x3 current matrices (cell array)
%         Generated by ControlPanel2 batch generator
%
% Output: 3D tensor [Samples, TimeSteps, Features] ready for Python/LSTM
%         X_LSTM  : [N x T x 9]  log1p-normalised wavelet energies
%         Y_LSTM  : [N x 1]      binary  (1 = internal fault → Trip)
%         Y_class : [N x 1]      4-class (1=Normal, 2=Inrush, 3=Internal, 4=External)
%         metadata: struct with labels, fault parameters, extraction config
%
% DWT configuration (2-level db4, 32-sample / 1-cycle window @ 1600 Hz):
%   D1  :  400 – 800 Hz  (high-freq transients, fault inception spike)
%   D2  :  200 – 400 Hz  (3rd / 5th harmonic content)
%   A2  :    0 – 200 Hz  (fundamental + 2nd harmonic — inrush discriminator)
%   → 3 energy coefficients × 3 phases = 9 features per timestep
%% =========================================================================

clear; clc; close all;

%% ═══════════════════════════════════════════════════════════════════════
%% 1. LOAD DATASET
%% ═══════════════════════════════════════════════════════════════════════

disp('╔═══════════════════════════════════════════════════════════╗');
disp('║     WAVELET FEATURE EXTRACTION FOR LSTM  (v2)             ║');
disp('╚═══════════════════════════════════════════════════════════╝');
disp(' ');

% Find the most recent dataset file.
% Searches in priority order:
%   1. TransformerProtection_Dataset_*.mat  (ControlPanel2 — mixed scenarios)
%   2. InrushDataset_*.mat                  (ControlPanel_Inrush — inrush only)
%   3. StressTestDataset.mat                (legacy filename)
fileList = dir('StressTestDataset_*.mat');
if isempty(fileList)
    fileList = dir('InrushDataset_*.mat');
end
if isempty(fileList)
    fileList = dir('StressTestDataset_*.mat');
end
if isempty(fileList)
    error(['No dataset files found. ' ...
           'Generate data using ControlPanel2 (mixed) or ControlPanel_Inrush (inrush).']);
end

% Sort by date and get the newest
[~, idx] = sort([fileList.datenum], 'descend');
filename = fileList(idx(1)).name;

disp([' Loading: ' filename]);
load(filename);
disp('✓ Dataset loaded successfully.');
disp(' ');

%% ═══════════════════════════════════════════════════════════════════════
%% 2. VALIDATE AND INSPECT DATA
%% ═══════════════════════════════════════════════════════════════════════

% Get dimensions from first sample
if isempty(dataset.primaryCurrent{1})
    error('Primary current data is empty! Check your simulation settings.');
end

[numSteps, numPhases] = size(dataset.primaryCurrent{1});
numSamples = length(dataset.zone);

% Validate data integrity
disp(' Dataset Information:');
disp(['   Total Samples : ' num2str(numSamples)]);
disp(['   Time Steps    : ' num2str(numSteps) '  (expected 1601)']);
disp(['   Phases        : ' num2str(numPhases) '  (A, B, C)']);
disp(' ');

% Check for missing data
validSamples = true(numSamples, 1);
for i = 1:numSamples
    if isempty(dataset.primaryCurrent{i}) || isempty(dataset.secondaryCurrent{i})
        validSamples(i) = false;
        warning('Sample %d has missing data - will be skipped', i);
    end
end

numValid = sum(validSamples);
if numValid < numSamples
    warning('%d samples have missing data and will be excluded', numSamples - numValid);
    disp(' ');
end

% Distribution summary
disp(' Scenario Distribution:');
disp(['   Normal:   ' num2str(sum(strcmp(dataset.zone, 'Normal')))   ' samples']);
disp(['   Inrush:   ' num2str(sum(strcmp(dataset.zone, 'Inrush')))   ' samples']);
disp(['   Internal: ' num2str(sum(strcmp(dataset.zone, 'Internal'))) ' samples  (should trip)']);
disp(['   External: ' num2str(sum(strcmp(dataset.zone, 'External'))) ' samples  (should NOT trip)']);
disp(' ');

%% ═══════════════════════════════════════════════════════════════════════
%% 3. FEATURE EXTRACTION CONFIGURATION
%% ═══════════════════════════════════════════════════════════════════════

%  Two-level db4 DWT on a 1-cycle sliding window
%  ─────────────────────────────────────────────
%  Sampling rate : 1600 Hz  →  1 cycle (50 Hz) = 32 samples
%  WindowSize    : 32 samples  (20 ms, 1 full cycle)
%  nLevels       : 2
%  Wavelet       : db4  (Daubechies-4, good for transient detection)
%
%  Frequency bands produced by 2-level db4 at 1600 Hz:
%    D1  :  400 – 800 Hz   (high-freq transients / fault spikes)
%    D2  :  200 – 400 Hz   (3rd and 5th harmonics)
%    A2  :    0 – 200 Hz   (fundamental 50 Hz + 2nd harmonic 100 Hz)
%
%  Features  :  [E_D1, E_D2, E_A2]  per phase  →  9 per timestep

WindowSize  = 32;          % samples — 1 full cycle at 1600 Hz
nLevels     = 2;           % two-level wavelet decomposition
wname       = 'db4';       % Daubechies-4

numFeatures    = numPhases * 3;              % 9 total
numTimeSteps   = numSteps - WindowSize;      % 1601 - 32 = 1569 valid timesteps

featureNames = {'E_D1_A','E_D2_A','E_A2_A', ...
                'E_D1_B','E_D2_B','E_A2_B', ...
                'E_D1_C','E_D2_C','E_A2_C'};

disp(' Feature Extraction Settings:');
disp(['   Wavelet          : ' wname '  (Daubechies-4)']);
disp(['   Window Size      : ' num2str(WindowSize) ' samples  (1 cycle at 1600 Hz = 20 ms)']);
disp(['   Decomposition    : ' num2str(nLevels) '-level  →  D1(400-800 Hz), D2(200-400 Hz), A2(0-200 Hz)']);
disp(['   Features/timestep: ' num2str(numFeatures)]);
disp(['   Valid timesteps  : ' num2str(numTimeSteps) '  (after 1-cycle warm-up)']);
disp(' ');

%% ═══════════════════════════════════════════════════════════════════════
%% 4. INITIALIZE OUTPUT TENSORS
%% ═══════════════════════════════════════════════════════════════════════

% Preallocate 3D tensor: [Samples, TimeSteps, Features]
% Indices run from 1 to numTimeSteps (no leading-zero warm-up rows)
X_LSTM  = zeros(numValid, numTimeSteps, numFeatures);
Y_LSTM  = zeros(numValid, 1);   % binary  : 1 = Internal Fault (Trip)
Y_class = zeros(numValid, 1);   % 4-class : 1=Normal 2=Inrush 3=Internal 4=External

%% ═══════════════════════════════════════════════════════════════════════
%% 5. MAIN FEATURE EXTRACTION LOOP
%% ═══════════════════════════════════════════════════════════════════════

disp(' Starting feature extraction...');
disp(' ');

wb = waitbar(0, 'Initializing feature extraction...', 'Name', 'Processing Dataset');
tic;

validIdx = 0;   % counter for rows written to output tensor

for i = 1:numSamples

    % ─── Skip samples flagged as invalid at load time ───────────────
    if ~validSamples(i)
        continue;
    end

    % ─── A. GET RAW CURRENT DATA ─────────────────────────────────────
    Ip = dataset.primaryCurrent{i};    % [1601 × 3]  Primary side
    Is = dataset.secondaryCurrent{i};  % [1601 × 3]  Secondary side

    % Validate dimensions BEFORE incrementing index
    if size(Ip, 1) ~= numSteps || size(Is, 1) ~= numSteps
        warning('Sample %d has inconsistent timesteps (%d/%d) - skipping', ...
                i, size(Ip,1), size(Is,1));
        continue;
    end

    % ─── Increment valid-sample counter (after validation) ───────────
    validIdx = validIdx + 1;

    % Update progress bar every 50 samples
    if mod(validIdx, 50) == 0 || validIdx == 1
        elapsed   = toc;
        remaining = (elapsed / validIdx) * (numValid - validIdx);
        waitbar(validIdx / numValid, wb, ...
                sprintf('Sample %d/%d | Elapsed: %.1fs | ETA: %.1fs', ...
                        validIdx, numValid, elapsed, remaining));
    end

    % ─── B. DIFFERENTIAL CURRENT ────────────────────────────────────
    % Use pre-computed differential if available (saves arithmetic)
    if isfield(dataset, 'diffCurrent') && ~isempty(dataset.diffCurrent{i})
        I_diff = dataset.diffCurrent{i};   % [1601 × 3]
    else
        I_diff = Ip - Is;                  % [1601 × 3]
    end

    % ─── C. SLIDING WINDOW TWO-LEVEL WAVELET FEATURE EXTRACTION ─────
    %
    % Window: [t-WindowSize+1 … t]  (past 32 samples ending at t)
    % First valid t = WindowSize+1 = 33  →  stored at output index 1
    % Last  valid t = numSteps    = 1601 →  stored at output index 1569
    %
    for t = (WindowSize + 1) : numSteps

        outIdx     = t - WindowSize;             % 1-based output index
        window_idx = (t - WindowSize + 1) : t;   % 32-sample window
        sig_window = I_diff(window_idx, :);       % [32 × 3]

        features_at_t = zeros(1, numFeatures);

        for ph = 1:numPhases
            signal = sig_window(:, ph);   % [32 × 1]  single phase

            % ── TWO-LEVEL DWT DECOMPOSITION ──────────────────────
            % C   : wavelet coefficient vector
            % L   : bookkeeping vector (lengths of each band)
            [C, L] = wavedec(signal, nLevels, wname);

            % Extract detail and approximation coefficients
            cD1 = detcoef(C, L, 1);              % D1: 400-800 Hz
            cD2 = detcoef(C, L, 2);              % D2: 200-400 Hz
            cA2 = appcoef(C, L, wname, 2);       % A2:   0-200 Hz

            % ── ENERGY = SUM OF SQUARED COEFFICIENTS ─────────────
            E_D1 = sum(cD1.^2);
            E_D2 = sum(cD2.^2);
            E_A2 = sum(cA2.^2);

            % ── PACK INTO FEATURE VECTOR ─────────────────────────
            % Layout: [E_D1_A, E_D2_A, E_A2_A,
            %          E_D1_B, E_D2_B, E_A2_B,
            %          E_D1_C, E_D2_C, E_A2_C]
            base = (ph - 1) * 3 + 1;
            features_at_t(base)     = E_D1;
            features_at_t(base + 1) = E_D2;
            features_at_t(base + 2) = E_A2;
        end

        % ── STORE IN TENSOR (contiguous from index 1) ────────────
        X_LSTM(validIdx, outIdx, :) = features_at_t;
    end

    % ─── D. STORE LABELS ─────────────────────────────────────────────
    % Binary label
    Y_LSTM(validIdx) = double(dataset.shouldTrip(i));

    % 4-class label
    switch dataset.zone{i}
        case 'Normal'
            Y_class(validIdx) = 1;
        case 'Inrush'
            Y_class(validIdx) = 2;
        case 'Internal'
            Y_class(validIdx) = 3;
        case 'External'
            Y_class(validIdx) = 4;
        otherwise
            Y_class(validIdx) = 0;   % unknown
    end
end

close(wb);
processingTime = toc;

disp(' ');
disp('  Feature extraction complete!');
disp(['   Processing time : ' num2str(processingTime, '%.1f') ' seconds']);
disp(['   Samples written : ' num2str(validIdx)]);
disp(' ');

%% ═══════════════════════════════════════════════════════════════════════
%% 6. LOG1P NORMALIZATION
%% ═══════════════════════════════════════════════════════════════════════
%
%  Wavelet energies span many orders of magnitude (e.g., 1e-6 to 1e6).
%  log1p(x) = log(1+x) maps [0, ∞) → [0, ∞) while:
%    • compressing large values
%    • preserving zero exactly (log1p(0) = 0)
%    • keeping relative ordering
%  This is applied BEFORE saving so Python can use X_LSTM directly.

disp(' Applying log1p normalization to energy features...');
X_LSTM = log1p(X_LSTM);
disp('   ✓ Normalization complete.');
disp(' ');

%% ═══════════════════════════════════════════════════════════════════════
%% 7. DATA VALIDATION AND STATISTICS
%% ═══════════════════════════════════════════════════════════════════════

disp(' Output Tensor Validation:');
disp(['   Shape    : ' mat2str(size(X_LSTM))]);
disp(['   Expected : [' num2str(validIdx) ', ' num2str(numTimeSteps) ', ' num2str(numFeatures) ']']);

if size(X_LSTM, 2) == numTimeSteps && size(X_LSTM, 3) == numFeatures
    disp('   ✓ Dimensions are CORRECT');
else
    error('   ✗ Dimension mismatch detected!');
end

% Check for NaN or Inf values
if any(isnan(X_LSTM(:))) || any(isinf(X_LSTM(:)))
    warning('   ⚠ Dataset contains NaN or Inf values!');
    disp(['      NaN count: ' num2str(sum(isnan(X_LSTM(:))))]);
    disp(['      Inf count: ' num2str(sum(isinf(X_LSTM(:))))]);
else
    disp('   ✓ No NaN/Inf values detected');
end

% Feature statistics (post log1p)
disp(' ');
disp(' Feature Statistics (after log1p normalization):');
for f = 1:numFeatures
    feat_data = X_LSTM(:, :, f);
    feat_data = feat_data(:);
    fprintf('   Feature %d  %-10s  range [%.3f, %.3f]  mean %.3f  std %.3f\n', ...
            f, featureNames{f}, min(feat_data), max(feat_data), ...
            mean(feat_data), std(feat_data));
end

% Label distribution
disp(' ');
disp(' Label Distribution:');
disp(['   Binary — Should Trip     (1): ' num2str(sum(Y_LSTM == 1))   ' samples']);
disp(['   Binary — Should NOT Trip (0): ' num2str(sum(Y_LSTM == 0))   ' samples']);
disp(['   Balance ratio: ' num2str(sum(Y_LSTM == 1) / length(Y_LSTM) * 100, '%.1f') '% positive class']);
disp(' ');
disp(' 4-class Distribution:');
disp(['   Normal   (1): ' num2str(sum(Y_class == 1)) ' samples']);
disp(['   Inrush   (2): ' num2str(sum(Y_class == 2)) ' samples']);
disp(['   Internal (3): ' num2str(sum(Y_class == 3)) ' samples']);
disp(['   External (4): ' num2str(sum(Y_class == 4)) ' samples']);

%% ═══════════════════════════════════════════════════════════════════════
%% 8. BUILD METADATA STRUCT AND SAVE
%% ═══════════════════════════════════════════════════════════════════════

disp(' ');
disp('📦 Packaging Metadata...');

% Single unified metadata struct
% (built here — does NOT overwrite any earlier struct)
metadata = struct();

% ── Extraction configuration ─────────────────────────────────────────
metadata.extractionConfig.windowSize      = WindowSize;
metadata.extractionConfig.nLevels         = nLevels;
metadata.extractionConfig.waveletName     = wname;
metadata.extractionConfig.samplingRate_Hz = 1600;
metadata.extractionConfig.features        = featureNames;
metadata.extractionConfig.freqBands       = struct( ...
    'D1_Hz', '400-800', ...
    'D2_Hz', '200-400', ...
    'A2_Hz', '0-200');
metadata.extractionConfig.normalization   = 'log1p applied to raw energies before saving';
metadata.extractionConfig.tensorShape     = sprintf('[%d samples, %d timesteps, %d features]', ...
                                             validIdx, numTimeSteps, numFeatures);
metadata.extractionConfig.sourceFile      = filename;
metadata.extractionConfig.extractedDate   = datetime('now');

% ── Scenario labels ───────────────────────────────────────────────────
metadata.zone            = dataset.zone;
metadata.faultType       = dataset.faultType;
metadata.faultResistance = dataset.faultResistance;
metadata.inceptionAngle  = dataset.inceptionAngle;
metadata.shouldTrip      = dataset.shouldTrip;

% ── Multi-class label map ─────────────────────────────────────────────
metadata.classMap = struct( ...
    'class1', 'Normal', ...
    'class2', 'Inrush', ...
    'class3', 'Internal_Fault', ...
    'class4', 'External_Fault');

% ── Optional stress-test fields (present only in stress-test datasets) ─
if isfield(dataset, 'stress_HIF')
    metadata.stress_HIF            = dataset.stress_HIF;
    metadata.stress_NoiseExtreme   = dataset.stress_NoiseExtreme;
    metadata.stress_CT_Saturation  = dataset.stress_CT_Saturation;
end

% ── Variability config (if recorded by ControlPanel2) ─────────────────
if isfield(dataset, 'metadata') && isfield(dataset.metadata, 'variabilityConfig')
    metadata.variabilityConfig = dataset.metadata.variabilityConfig;
end

% ── SAVE ──────────────────────────────────────────────────────────────
timestamp      = datestr(now, 'yyyymmdd_HHMMSS');
outputFilename = ['LSTM_Features_' timestamp '.mat'];

save(outputFilename, 'X_LSTM', 'Y_LSTM', 'Y_class', 'metadata', '-v7.3');

disp(['✅ Saved: ' outputFilename]);

%% ═══════════════════════════════════════════════════════════════════════
%% 9. SUMMARY REPORT
%% ═══════════════════════════════════════════════════════════════════════

disp(' ');
disp('╔═══════════════════════════════════════════════════════════╗');
disp('║                  PROCESSING COMPLETE                      ║');
disp('╚═══════════════════════════════════════════════════════════╝');
disp(' ');
disp(' Summary:');
disp(['   Input file     : ' filename]);
disp(['   Output file    : ' outputFilename]);
disp(['   Tensor shape   : [' num2str(size(X_LSTM, 1)) ' samples, ' ...
                              num2str(size(X_LSTM, 2)) ' timesteps, ' ...
                              num2str(size(X_LSTM, 3)) ' features]']);
disp(['   Processing time: ' num2str(processingTime, '%.1f') ' s']);
disp(' ');
disp(' Python usage:');
disp('   import scipy.io');
disp('   d = scipy.io.loadmat(''<filename>.mat'', simplify_cells=True)');
disp('   X = d[''X_LSTM'']      # (N, 1569, 9)  float64, log1p-normalised');
disp('   Y = d[''Y_LSTM'']      # (N,)           binary  0/1');
disp('   Yc= d[''Y_class'']     # (N,)           4-class 1/2/3/4');
